"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { ArrowLeft, Mail, Lock, Eye, EyeOff, User } from "lucide-react";
import { useUserStore } from "@/store/userStore";

export default function CadastroPage() {
  const router = useRouter();
  const login = useUserStore(state => state.login);

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);

  const handleRegister = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !email || !password) return;

    // Simula o cadastro e já faz login
    login(name, email);

    // Redireciona para a home
    router.push("/");
  };

  return (
    <main className="flex-1 flex flex-col min-h-screen bg-white">
      {/* Header */}
      <header className="px-6 py-4 flex items-center">
        <button onClick={() => router.back()} className="w-10 h-10 flex items-center justify-center -ml-2 text-stone-900 rounded-full hover:bg-stone-50 active:scale-95 transition-all">
          <ArrowLeft className="w-6 h-6" />
        </button>
      </header>

      <div className="flex-1 px-6 pb-8 flex flex-col mt-4">
        <h1 className="text-3xl font-bold text-stone-900 mb-2">Criar Conta 🚀</h1>
        <p className="text-stone-500 mb-8 font-medium">Junte-se a nós e peça suas comidas favoritas.</p>

        <form onSubmit={handleRegister} className="flex flex-col gap-4">
          {/* Name Input */}
          <div className="flex flex-col gap-1.5">
            <label className="text-sm font-bold text-stone-700 ml-1">Nome Completo</label>
            <div className="relative flex items-center">
              <div className="absolute left-4 text-stone-400">
                <User className="w-5 h-5" />
              </div>
              <input 
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Seu nome"
                className="w-full bg-stone-50 border border-stone-200 rounded-2xl py-4 pl-12 pr-4 text-stone-900 outline-none focus:border-brand-500 focus:bg-white transition-all font-medium"
                required
              />
            </div>
          </div>

          {/* Email Input */}
          <div className="flex flex-col gap-1.5 mt-2">
            <label className="text-sm font-bold text-stone-700 ml-1">E-mail</label>
            <div className="relative flex items-center">
              <div className="absolute left-4 text-stone-400">
                <Mail className="w-5 h-5" />
              </div>
              <input 
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="seu@email.com"
                className="w-full bg-stone-50 border border-stone-200 rounded-2xl py-4 pl-12 pr-4 text-stone-900 outline-none focus:border-brand-500 focus:bg-white transition-all font-medium"
                required
              />
            </div>
          </div>

          {/* Password Input */}
          <div className="flex flex-col gap-1.5 mt-2">
            <label className="text-sm font-bold text-stone-700 ml-1">Senha</label>
            <div className="relative flex items-center">
              <div className="absolute left-4 text-stone-400">
                <Lock className="w-5 h-5" />
              </div>
              <input 
                type={showPassword ? "text" : "password"}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                className="w-full bg-stone-50 border border-stone-200 rounded-2xl py-4 pl-12 pr-12 text-stone-900 outline-none focus:border-brand-500 focus:bg-white transition-all font-medium"
                required
              />
              <button 
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-4 text-stone-400 p-1 hover:text-stone-600"
              >
                {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
              </button>
            </div>
          </div>

          {/* Register Button */}
          <button 
            type="submit"
            className="w-full bg-brand-500 text-white rounded-full py-4 font-bold shadow-lg shadow-brand-500/30 active:scale-[0.98] transition-all mt-6"
          >
            Criar Conta
          </button>
        </form>

        {/* Divider */}
        <div className="flex items-center gap-4 my-8">
          <div className="flex-1 h-px bg-stone-100"></div>
          <span className="text-stone-400 text-sm font-medium">Ou continue com</span>
          <div className="flex-1 h-px bg-stone-100"></div>
        </div>

        {/* Social Login */}
        <div className="flex flex-col gap-3">
          <button type="button" className="w-full bg-white border border-stone-200 rounded-full py-3.5 flex items-center justify-center gap-3 font-bold text-stone-700 hover:bg-stone-50 active:scale-[0.98] transition-all">
            <img src="https://www.svgrepo.com/show/475656/google-color.svg" alt="Google" className="w-5 h-5" />
            Google
          </button>
        </div>

        {/* Login Link */}
        <div className="mt-auto pt-8 flex justify-center text-sm font-medium">
          <span className="text-stone-500">Já tem uma conta? </span>
          <Link href="/login" className="text-brand-500 font-bold ml-1 hover:underline">
            Entrar
          </Link>
        </div>
      </div>
    </main>
  );
}

