"use client";

import { ArrowLeft, MapPin, Plus, Trash2, Home, Briefcase } from "lucide-react";
import { useRouter } from "next/navigation";
import { useUserStore } from "@/store/userStore";
import { useState, useEffect } from "react";

export default function EnderecosPage() {
  const router = useRouter();
  const { isAuthenticated } = useUserStore();
  const [mounted, setMounted] = useState(false);

  // Endereços mockados para a demonstração
  const [enderecos, setEnderecos] = useState([
    { id: 1, title: "Casa", street: "Rua Virgílio Rodrigues Oliveira", number: "177", district: "Centro", city: "São Paulo", state: "SP", isDefault: true, type: "home" },
    { id: 2, title: "Trabalho", street: "Av. Paulista", number: "1000", district: "Bela Vista", city: "São Paulo", state: "SP", isDefault: false, type: "work" },
  ]);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) return null;

  if (!isAuthenticated) {
    router.push("/login");
    return null;
  }

  const handleDelete = (id: number) => {
    if (confirm("Tem certeza que deseja remover este endereço?")) {
      setEnderecos(enderecos.filter(e => e.id !== id));
    }
  };

  const handleSetDefault = (id: number) => {
    setEnderecos(enderecos.map(e => ({
      ...e,
      isDefault: e.id === id
    })));
  };

  return (
    <main className="flex-1 flex flex-col bg-stone-50 min-h-screen pb-24">
      <header className="px-6 py-4 flex items-center bg-white sticky top-0 z-10 border-b border-stone-100 shadow-sm">
        <button onClick={() => router.back()} className="w-10 h-10 flex items-center justify-center -ml-2 text-stone-900">
          <ArrowLeft className="w-6 h-6" />
        </button>
        <h1 className="flex-1 text-center text-xl font-bold text-stone-900 pr-8">Endereços</h1>
      </header>

      <div className="flex-1 p-6 max-w-2xl mx-auto w-full flex flex-col gap-4">
        {enderecos.map(endereco => (
          <div 
            key={endereco.id} 
            onClick={() => handleSetDefault(endereco.id)}
            className={`bg-white p-5 rounded-3xl border transition-all cursor-pointer shadow-[0_4px_24px_rgba(0,0,0,0.02)] ${endereco.isDefault ? 'border-brand-500 ring-1 ring-brand-500/20' : 'border-stone-100 hover:border-stone-300'}`}
          >
            <div className="flex items-start gap-4">
              <div className={`w-12 h-12 rounded-full flex items-center justify-center shrink-0 ${endereco.isDefault ? 'bg-brand-50 text-brand-500' : 'bg-stone-50 text-stone-400'}`}>
                {endereco.type === 'home' ? <Home className="w-6 h-6" /> : endereco.type === 'work' ? <Briefcase className="w-6 h-6" /> : <MapPin className="w-6 h-6" />}
              </div>
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <h3 className="font-bold text-stone-900 text-lg">{endereco.title}</h3>
                  {endereco.isDefault && (
                    <span className="bg-brand-50 text-brand-500 text-[10px] font-bold px-2 py-0.5 rounded-md uppercase tracking-wider">Principal</span>
                  )}
                </div>
                <p className="text-stone-500 text-sm leading-relaxed">
                  {endereco.street}, {endereco.number}<br />
                  {endereco.district}, {endereco.city} - {endereco.state}
                </p>
              </div>
              <button 
                onClick={(e) => { e.stopPropagation(); handleDelete(endereco.id); }} 
                className="w-10 h-10 flex items-center justify-center text-stone-300 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
              >
                <Trash2 className="w-5 h-5" />
              </button>
            </div>
          </div>
        ))}

        <button className="mt-4 flex items-center justify-center gap-2 border-2 border-dashed border-brand-200 text-brand-500 font-bold bg-brand-50 hover:bg-brand-100 rounded-3xl p-5 transition-colors group">
          <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center shadow-sm group-hover:scale-110 transition-transform">
            <Plus className="w-5 h-5" />
          </div>
          Adicionar Novo Endereço
        </button>
      </div>
    </main>
  );
}

