                  <div className="w-10 h-10 rounded-full bg-stone-50 flex items-center justify-center text-stone-600">
                    <item.icon className="w-5 h-5" />
                  </div>
                  <span className="font-bold text-stone-800">{item.label}</span>
                </div>
