          </div>
        </div>
      </div>

      <BottomNavigation />

      <NotificationsModal 
        isOpen={isNotificationsModalOpen} 
        onClose={() => setIsNotificationsModalOpen(false)} 
      />
    </main>
  );
}

"use client";

import { useState } from "react";
import { ArrowLeft, Star, Minus, Plus } from "lucide-react";
import { useRouter } from "next/navigation";
import { useCartStore } from "@/store/cartStore";

export default function RestaurantPage() {
  const router = useRouter();
  const addItem = useCartStore((state) => state.addItem);
  const [quantity, setQuantity] = useState(1);

  const product = {
    id: "prod-1",
    restaurantId: "1",
    name: "Macarrão Vegetariano",
    price: 12.00,
    rating: 4.8,
    reviews: 4200,
    image: "https://images.unsplash.com/photo-1512152272829-e3139592d56f?q=80&w=600&auto=format&fit=crop",
    description: "Nossa salada mista exclusiva com verduras orgânicas frescas, tomates cereja, pepinos, cenouras e nosso molho especial da casa. Perfeita para uma refeição saudável e satisfatória.",
  };

  const handleAddToCart = () => {
    addItem({
      id: product.id,
      restaurantId: product.restaurantId,
      name: product.name,
      price: product.price,
      quantity,
    });
    router.push("/carrinho");
  };

  return (
    <main className="flex-1 flex flex-col bg-white min-h-screen relative pb-32">
      {/* Floating Back Button */}
      <button 
        onClick={() => router.back()}
        className="absolute top-12 left-6 z-20 w-12 h-12 bg-white/30 backdrop-blur-md rounded-full flex items-center justify-center shadow-sm text-stone-900 border border-white/20"
      >
        <ArrowLeft className="w-6 h-6" />
      </button>

      {/* Header Image */}
      <div className="w-full h-80 relative bg-stone-200">
        <img src={product.image} alt={product.name} className="w-full h-full object-cover" />
      </div>

      {/* Content */}
      <div className="flex-1 px-6 pt-6 bg-white relative -mt-8 rounded-t-[32px]">
        {/* Title & Badge */}
        <div className="flex justify-between items-start mb-2 mt-4">
          <h1 className="text-3xl font-bold text-stone-900 leading-tight w-3/4">{product.name}</h1>
        </div>

        {/* Rating & Distance */}
        <div className="flex items-center gap-4 border-b border-stone-100 pb-6 mb-6 mt-4">
          <div className="flex items-center gap-1.5">
            <Star className="w-5 h-5 text-brand-500 fill-brand-500" />
            <span className="font-bold text-lg text-stone-900">{product.rating}</span>
            <span className="text-stone-400 font-medium text-sm">({(product.reviews / 1000).toFixed(1)}k avaliações)</span>
          </div>
        </div>

        {/* Description */}
        <h2 className="text-xl font-bold mb-3">Descrição</h2>
        <p className="text-stone-500 leading-relaxed font-medium text-[15px]">
          {product.description}
        </p>

        {/* Quantity Selector */}
        <div className="flex items-center justify-between mt-10 p-4 rounded-3xl border border-stone-100 shadow-[0_4px_20px_rgba(0,0,0,0.02)]">
          <span className="text-stone-500 font-medium ml-2">Preço Total</span>
          <div className="flex items-center gap-6">
            <button 
              onClick={() => setQuantity(Math.max(1, quantity - 1))}
              className="w-10 h-10 rounded-full border border-stone-200 flex items-center justify-center bg-white text-stone-900 shadow-sm"
            >
              <Minus className="w-5 h-5" />
            </button>
            <span className="font-bold text-xl min-w-[1.5rem] text-center">{quantity}</span>
            <button 
              onClick={() => setQuantity(quantity + 1)}
              className="w-10 h-10 rounded-full bg-brand-500 flex items-center justify-center text-white shadow-md shadow-brand-200"
            >
              <Plus className="w-5 h-5" />
            </button>
          </div>
        </div>
      </div>

      {/* Floating Add to Cart Button */}
      <div className="fixed bottom-0 left-0 w-full p-6 bg-white border-t border-stone-50 rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.05)] z-50">
        <button 
          onClick={handleAddToCart}
          className="w-full bg-brand-500 text-white rounded-full py-4 px-6 flex items-center justify-between shadow-lg shadow-brand-500/30 transition-transform active:scale-[0.98]"
        >
          <span className="text-base font-bold">Adicionar ao Carrinho</span>
          <span className="text-base font-bold">R$ {(product.price * quantity).toFixed(2).replace('.', ',')}</span>
        </button>
      </div>
    </main>
  );
}

"use client";

import { useState } from "react";
import { X, MapPin, Navigation, Search, Loader2 } from "lucide-react";
import { useUserStore } from "@/store/userStore";

interface AddressModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function AddressModal({ isOpen, onClose }: AddressModalProps) {
  const setAddress = useUserStore((state) => state.setAddress);

  const [loadingGps, setLoadingGps] = useState(false);
  const [gpsError, setGpsError] = useState("");

  // States para o modo "Completar número"
  const [streetData, setStreetData] = useState<any>(null);
  const [houseNumber, setHouseNumber] = useState("");
  const [isAskingNumber, setIsAskingNumber] = useState(false);

  // States para busca manual
  const [manualAddress, setManualAddress] = useState("");

  const handleGetLocation = () => {
    setGpsError("");
    setLoadingGps(true);

    if (!navigator.geolocation) {
      setGpsError("Seu navegador não suporta geolocalização.");
      setLoadingGps(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude } = position.coords;
        try {
          // OpenStreetMap Nominatim API
          const response = await fetch(
            `https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}&zoom=18&addressdetails=1`
          );
          const data = await response.json();

          if (data && data.address) {
            const road = data.address.road || data.address.pedestrian || data.address.street || "Rua Desconhecida";
            const neighborhood = data.address.suburb || data.address.neighbourhood || "";
            const city = data.address.city || data.address.town || "";
            const state = data.address.state || "";

            setStreetData({
              street: road,
              neighborhood,
              city,
              state,
              lat: latitude,
              lon: longitude
            });
            setIsAskingNumber(true);
          } else {
            setGpsError("Não foi possível encontrar o endereço para essa localização.");
          }
        } catch (error) {
          setGpsError("Erro ao conectar com o serviço de mapas.");
        } finally {
          setLoadingGps(false);
        }
      },
      (error) => {
        setGpsError("Permissão negada ou erro ao obter localização.");
        setLoadingGps(false);
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  const handleConfirmNumber = () => {
    if (!houseNumber.trim()) return;

    setAddress({
      street: streetData.street,
      number: houseNumber,
      neighborhood: streetData.neighborhood,
      city: streetData.city,
      state: streetData.state,
      lat: streetData.lat,
      lon: streetData.lon
    });

    closeAndReset();
  };

  const handleManualSubmit = () => {
    if (!manualAddress.trim()) return;

    // Simplificação para endereço manual sem API
    setAddress({
      street: manualAddress,
      number: "S/N",
    });

    closeAndReset();
  };

  const closeAndReset = () => {
    onClose();
    setTimeout(() => {
      setIsAskingNumber(false);
      setHouseNumber("");
      setStreetData(null);
      setGpsError("");
      setManualAddress("");
    }, 300);
  };

  if (!isOpen && !isAskingNumber) return null; // Small optimization

  return (
    <div style={{ zIndex: 99999 }} className={`fixed inset-0 flex items-end justify-center ${isOpen ? 'pointer-events-auto' : 'pointer-events-none'}`}>
      {/* Backdrop */}
      <div 
        className={`absolute inset-0 bg-stone-900/60 backdrop-blur-sm transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0'}`}
        onClick={closeAndReset}
      />

      {/* Bottom Sheet */}
      <div 
        className={`w-full bg-white rounded-t-[40px] shadow-2xl relative z-10 flex flex-col max-h-[90vh] transition-transform duration-300 ${isOpen ? 'translate-y-0' : 'translate-y-full'}`}
      >
        <button 
          onClick={closeAndReset}
          className="absolute top-6 right-6 z-20 w-10 h-10 bg-stone-100 rounded-full flex items-center justify-center text-stone-600 hover:bg-stone-200 transition-colors"
        >
          <X className="w-5 h-5" />
        </button>

        <div className="p-8 pt-10 pb-12 overflow-y-auto">
          {!isAskingNumber ? (
            <>
              <h2 className="text-2xl font-bold text-stone-900 mb-2">Onde você está?</h2>
              <p className="text-stone-500 mb-8 text-sm">Adicione seu endereço para ver o tempo de entrega exato e a taxa.</p>

              <button 
                onClick={handleGetLocation}
                disabled={loadingGps}
                className="w-full bg-brand-50 text-brand-600 border border-brand-100 rounded-2xl p-4 flex items-center gap-4 mb-6 hover:bg-brand-100 transition-colors active:scale-[0.98]"
              >
                <div className="w-10 h-10 rounded-full bg-white flex items-center justify-center shadow-sm">
                  {loadingGps ? (
                    <Loader2 className="w-5 h-5 text-brand-500 animate-spin" />
                  ) : (
                    <Navigation className="w-5 h-5 text-brand-500" />
                  )}
                </div>
                <div className="flex flex-col text-left">
                  <span className="font-bold">Usar minha localização atual</span>
                  <span className="text-xs text-brand-500/80">Ativar GPS</span>
                </div>
              </button>

              {gpsError && (
                <div className="mb-6 p-3 bg-red-50 text-red-500 text-xs rounded-xl font-medium border border-red-100">
                  {gpsError}
                </div>
              )}

              <div className="flex items-center gap-4 mb-6">
                <div className="h-px bg-stone-100 flex-1"></div>
                <span className="text-xs font-bold text-stone-300 uppercase tracking-widest">OU</span>
                <div className="h-px bg-stone-100 flex-1"></div>
              </div>

              <div className="relative flex items-center w-full mb-4">
                <Search className="w-5 h-5 text-stone-400 absolute left-4" />
                <input 
                  type="text" 
                  value={manualAddress}
                  onChange={(e) => setManualAddress(e.target.value)}
                  placeholder="Digite seu endereço e número..." 
                  className="w-full pl-12 pr-4 py-4 bg-stone-50 border border-stone-200 rounded-2xl text-stone-800 placeholder-stone-400 focus:outline-none focus:border-brand-500 focus:ring-1 focus:ring-brand-500 transition-all font-medium text-base"
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') handleManualSubmit();
                  }}
                />
              </div>
              <button 
                onClick={handleManualSubmit}
                disabled={!manualAddress.trim()}
                className="w-full bg-stone-900 text-white rounded-2xl py-4 font-bold disabled:opacity-50 disabled:active:scale-100 active:scale-[0.98] transition-transform"
              >
                Confirmar Endereço Manual
              </button>
            </>
          ) : (
            <>
              {/* Tela 2: Pedir o número da casa */}
              <div className="flex items-center gap-3 mb-6">
                <div className="w-12 h-12 bg-brand-100 rounded-full flex items-center justify-center">
                  <MapPin className="w-6 h-6 text-brand-500" />
                </div>
                <div>
                  <h3 className="text-stone-400 text-xs uppercase font-bold tracking-wider mb-1">Rua Encontrada</h3>
                  <p className="font-bold text-lg text-stone-900 leading-tight">{streetData?.street}</p>
                </div>
              </div>

              <h2 className="text-xl font-bold text-stone-900 mb-2">Qual o número do local?</h2>
              <p className="text-stone-500 mb-6 text-sm">Precisamos do número para a entrega.</p>

              <input 
                type="text" 
                value={houseNumber}
                onChange={(e) => setHouseNumber(e.target.value)}
                placeholder="Ex: 123, 45B, S/N..." 
                autoFocus
                className="w-full px-4 py-4 bg-stone-50 border border-stone-200 rounded-2xl text-stone-800 placeholder-stone-400 focus:outline-none focus:border-brand-500 focus:ring-1 focus:ring-brand-500 transition-all font-bold text-lg mb-6 text-center"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleConfirmNumber();
                }}
              />

              <button 
                onClick={handleConfirmNumber}
                disabled={!houseNumber.trim()}
                className="w-full bg-brand-500 text-white rounded-2xl py-4 font-bold disabled:opacity-50 disabled:active:scale-100 active:scale-[0.98] transition-transform shadow-lg shadow-brand-500/30"
              >
                Salvar Endereço
              </button>

              <button 
                onClick={() => setIsAskingNumber(false)}
                className="w-full mt-4 text-stone-400 font-bold text-sm py-2"
              >
                Voltar
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

