"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { ShoppingBag, Home, FileText, User } from "lucide-react";
import { useState, useEffect } from "react";

import { useCartStore } from "@/store/cartStore";

export function BottomNavigation() {
  const pathname = usePathname();
  const items = useCartStore(state => state.items);
  const itemCount = items.reduce((acc, item) => acc + item.quantity, 0);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const isActive = (path: string) => pathname === path;

  // Hide BottomNavigation on specific checkout/tracking flows
  if (pathname === "/carrinho" || pathname === "/login" || pathname === "/cadastro" || (pathname.startsWith("/pedidos/") && pathname !== "/pedidos")) {
    return null;
  }

  return (
    <nav className="fixed lg:hidden bottom-0 left-0 w-full bg-white border-t border-stone-100 px-2 py-2 pb-[env(safe-area-inset-bottom,1rem)] flex justify-around items-center z-50 shadow-[0_-4px_24px_rgba(0,0,0,0.02)]">
      <Link href="/" className={`flex flex-col items-center justify-center min-w-[70px] gap-1 transition-colors ${isActive("/") ? "text-brand-500" : "text-stone-400 hover:text-stone-900"}`}>
        <Home className="w-[22px] h-[22px]" strokeWidth={isActive("/") ? 2.5 : 2} />
        <span className="text-[10px] font-medium tracking-wide">Início</span>
      </Link>

      <Link href="/pedidos" className={`flex flex-col items-center justify-center min-w-[70px] gap-1 transition-colors ${isActive("/pedidos") || pathname.startsWith("/pedidos/") ? "text-brand-500" : "text-stone-400 hover:text-stone-900"}`}>
