        <span className="text-[10px] font-medium tracking-wide">Pedidos</span>
      </Link>

      <Link href="/carrinho" className={`flex flex-col items-center justify-center min-w-[70px] gap-1 transition-colors relative ${isActive("/carrinho") ? "text-brand-500" : "text-stone-400 hover:text-stone-900"}`}>
        {mounted && itemCount > 0 && (
          <div className="absolute top-0 right-[20px] w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white" />
        )}
        <ShoppingBag className="w-[22px] h-[22px]" strokeWidth={isActive("/carrinho") ? 2.5 : 2} />
